/* ============================================================
  联络by梨 qq模式适配
  翻译模块来自妞妞，引用模块来自小汐。老婆宝宝们我好爱你们TvT
   ============================================================ */

/* ============================================================
   模块一：顶栏（整体可上下移动）—— 已调整标题与按钮持平
   ============================================================ */

html .chat-detail-screen .chat-header-custom,
html .chat-detail-screen .glass-header {
  position: relative !important;
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  padding-bottom: 41px !important;
  min-height: 30px !important;
  border-bottom: none !important;
  /* 若需整体上下移动整个顶栏，可在此处使用 transform: translateY(0px); 并修改数值 */
}

/* ---------- 左上 "Edit" 按钮 ---------- */
html .chat-detail-screen .header-btn-back svg {
  display: none !important;
}
html .chat-detail-screen .header-btn-back {
  font-size: 0 !important;
  padding: 0 !important;
  min-width: 70px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: flex-start !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}
html .chat-detail-screen .header-btn-back::before {
  content: "Edit";
  font-weight: 700;
  font-size: 15px;
  color: #1c1c1e;
  background: #e7e7e7;
  padding: 4px 14px;
  border-radius: 16px;
  line-height: 1.4;
  display: inline-block;
  transition: background 0.2s;
}
html .chat-detail-screen .header-btn-back:hover::before {
  background: #d1d1d6;
}

/* ---------- 隐藏头像 ---------- */
html .chat-detail-screen .header-avatar-container {
  display: none !important;
}

/* ---------- 标题（含小字装饰）—— 调整此处实现与按钮持平 ---------- */
html .chat-detail-screen .header-profile-section {
  position: absolute !important;
  left: 50% !important;
  top: 50% !important;                /* 垂直居中基准 */
  transform: translate(-50%, -50%) translateY(12px) !important;
  /* 🤍 上下微调：修改 translateY(12px) 中的数值
       正数（如 5px）→ 整体下移
       负数（如 -5px）→ 整体上移
       调整此值可使标题与左右按钮视觉持平 */
  display: block !important;
  flex: none !important;
  margin: 0 !important;
  padding: 0 !important;
  width: auto !important;
  height: auto !important;
  text-align: center !important;
  white-space: normal !important;
}

html .chat-detail-screen .chat-header-title {
  display: block !important;
  position: static !important;
  transform: none !important;
  left: auto !important;
  top: auto !important;
  text-align: center !important;
  margin: 0 !important;
  padding: 0 !important;
  font-size: 17px;
  font-weight: 600;
  line-height: 1.3;
}

/* 🖤 顶栏名字下方装饰性文本：修改 content 即可 */
html .chat-detail-screen .chat-header-title::after {
  content: "@ 사용자 로그인 상태";
  display: block;
  font-size: 11px;
  font-weight: 500;
  color: #8e8e93;
  margin-top: 2px;
  text-align: center;
  letter-spacing: 0.5px;
}

/* ---------- 背景条和标签（中间三个按钮的装饰） ---------- */
html .chat-detail-screen .chat-header-custom::before {
  content: '' !important;
  position: absolute !important;
  bottom: 9px !important;
  left: 11px !important;
  right: 9px !important;
  height: 25px !important;
  background: 
    linear-gradient(to left, #e3e3e3 0%, #e3e3e3 26%, transparent 26%, transparent 100%) 0 0 / 100% 100% no-repeat,
    linear-gradient(to right, #efefef 0%, #efefef 100%) 0 0 / 100% 100% no-repeat;
  border-radius: 14px !important;
  pointer-events: none !important;
  z-index: 1 !important;
}

html .chat-detail-screen .chat-header-custom::after {
  content: " Likes                                Search                          Contact";
  position: absolute !important;
  bottom: 14px !important;
  left: 16px !important;
  right: 13px !important;
  font-family: -apple-system, "Helvetica Neue", sans-serif !important;
  font-size: 15px !important;
  font-weight: 450 !important;
  color: #8e8e93 !important;
  white-space: pre !important;
  letter-spacing: normal !important;
  text-align: left !important;
  z-index: 2 !important;
  line-height: 1 !important;
}

/* ---------- 隐藏通话/视频按钮（但保留点击区域） ---------- */
html .chat-detail-screen .header-btn-phone,
html .chat-detail-screen .header-btn-video {
  opacity: 0 !important;
  pointer-events: auto !important;
}

/* ---------- 右上 "Done" 按钮 ---------- */
html .chat-detail-screen .header-btn-info svg,
html .chat-detail-screen .header-btn-info img {
  display: none !important;
}
html .chat-detail-screen .header-btn-info {
  font-size: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  min-width: 50px !important;
  min-height: 44px !important;
}
html .chat-detail-screen .header-btn-info::before {
  content: "Done";
  font-weight: 700;
  font-size: 18px;
  color: #1c1c1e;
  display: inline-block;
  line-height: 1.4;
  transition: opacity 0.2s;
}
html .chat-detail-screen .header-btn-info:hover::before {
  opacity: 0.7;
}

html .chat-detail-screen .header-btn-phone,
html .chat-detail-screen .header-btn-video,
html .chat-detail-screen .header-btn-info,
html .chat-detail-screen .header-action-btn {
  flex: 0 0 auto !important;
  margin-left: 4px;
}

/* ============================================================
   QQ 模式气泡完整模块（包含头像、气泡、间距、小尾巴）
   小尾巴用 mask 方式
   ============================================================ */

/* ---------- 头像显示规则 ---------- */
[data-theme-style="qq"] .msg-avatar-them-container,
[data-theme-style="qq"] .msg-avatar-me-container {
    visibility: hidden !important;
}
[data-theme-style="qq"] .msg-avatar-them-container.is-first,
[data-theme-style="qq"] .msg-avatar-them-container.is-single,
[data-theme-style="qq"] .msg-avatar-me-container.is-first,
[data-theme-style="qq"] .msg-avatar-me-container.is-single {
    visibility: visible !important;
    position: relative !important;
}

/* 🖤 对方头像下方装饰性昵称 */
[data-theme-style="qq"] .msg-avatar-them-container.is-first::after,
[data-theme-style="qq"] .msg-avatar-them-container.is-single::after {
    content: "@ㅎㅎ" !important;
    position: absolute !important;
    left: 50% !important;
    top: calc(100% + 4px) !important;
    transform: translateX(-50%) !important;
    font-size: 11px !important;
    font-weight: 500 !important;
    color: #6c6c70 !important;
    white-space: nowrap !important;
    letter-spacing: 0.3px !important;
    opacity: 0.8 !important;
    pointer-events: none !important;
}

/* 🖤 我方头像下方装饰性昵称 */
[data-theme-style="qq"] .msg-avatar-me-container.is-first::after,
[data-theme-style="qq"] .msg-avatar-me-container.is-single::after {
    content: "ㅇㅈㅇ" !important;
    position: absolute !important;
    left: 50% !important;
    top: calc(100% + 4px) !important;
    transform: translateX(-50%) !important;
    font-size: 11px !important;
    font-weight: 500 !important;
    color: #6c6c70 !important;
    white-space: nowrap !important;
    letter-spacing: 0.3px !important;
    opacity: 0.8 !important;
    pointer-events: none !important;
}

/* ---------- 气泡基础样式 ---------- */
[data-theme-style="qq"] .bubble-me-custom,
[data-theme-style="qq"] .bubble-them-custom {
    padding: 6px 10px !important;
    font-size: 13px !important;
    border-radius: 16px !important;
    box-shadow: none !important;
    text-shadow: none !important;
    position: relative !important;
    overflow: visible !important;
    border: none !important;
    outline: none !important;
}

[data-theme-style="qq"] .bubble-them-custom {
    background: #3a3a3a !important;
    color: #ffffff !important;
    transform: translateX(5px) !important;
}

[data-theme-style="qq"] .bubble-me-custom {
    background: #e8e8e8 !important;
    color: #2a2a2a !important;
    transform: translateX(-5px) !important;
}

/* ---------- 气泡圆角修饰（连发分组） ---------- */
[data-theme-style="qq"] .bubble-me-custom.first {
    border-radius: 16px 16px 6px 16px !important;
}
[data-theme-style="qq"] .bubble-me-custom.mid {
    border-radius: 16px 6px 6px 16px !important;
}
[data-theme-style="qq"] .bubble-me-custom.last {
    border-radius: 16px 6px 16px 16px !important;
}
[data-theme-style="qq"] .bubble-them-custom.first {
    border-radius: 16px 16px 16px 6px !important;
}
[data-theme-style="qq"] .bubble-them-custom.mid {
    border-radius: 6px 16px 16px 6px !important;
}
[data-theme-style="qq"] .bubble-them-custom.last {
    border-radius: 6px 16px 16px 16px !important;
}

/* ---------- 气泡内链接和引用颜色 ---------- */
[data-theme-style="qq"] .bubble-them-custom a,
[data-theme-style="qq"] .bubble-them-custom .msg-reply-block,
[data-theme-style="qq"] .bubble-them-custom .msg-translation-btn {
    color: #ffffff !important;
}
[data-theme-style="qq"] .bubble-me-custom a,
[data-theme-style="qq"] .bubble-me-custom .msg-reply-block,
[data-theme-style="qq"] .bubble-me-custom .msg-translation-btn {
    color: #2a2a2a !important;
}

/* ============================================================
   气泡间距控制（统一：首条/中间条均为 7px，末尾/单条为 30px）
   ============================================================ */

/* 不同组之间的大间距 */
[data-theme-style="qq"] .msg-bubble-wrapper {
    margin-bottom: 30px !important;
}

/* 同组连续消息的小间距（统一为 7px，不再受翻译影响） */
[data-theme-style="qq"] .msg-bubble-wrapper.is-first,
[data-theme-style="qq"] .msg-bubble-wrapper.is-mid {
    margin-bottom: 7px !important;
}

/* 移除之前“有翻译时加大间距”的特殊规则，现已统一 */

/* ============================================================
   小尾巴装饰（mask 方式 + 原定位 + z-index: 5）
   ============================================================ */

/* 对方小尾巴（左侧） */
[data-theme-style="qq"] .msg-bubble-wrapper.is-first .bubble-them-custom::before,
[data-theme-style="qq"] .msg-bubble-wrapper.is-single .bubble-them-custom::before {
    content: "" !important;
    position: absolute !important;
    bottom: -8px !important;
    left: -15px !important;
    width: 42px !important;
    height: 42px !important;
    background-color: #3a3a3a !important;

    -webkit-mask: url("https://i.postimg.cc/sD2H6QGM/071D6807C255F1580E4BA9234A1A3C33.png") no-repeat center / contain;
    mask: url("https://i.postimg.cc/sD2H6QGM/071D6807C255F1580E4BA9234A1A3C33.png") no-repeat center / contain;

    pointer-events: none !important;
    z-index: 5 !important;
}

/* 我方小尾巴（右侧） */
[data-theme-style="qq"] .msg-bubble-wrapper.is-first .bubble-me-custom::before,
[data-theme-style="qq"] .msg-bubble-wrapper.is-single .bubble-me-custom::before {
    content: "" !important;
    position: absolute !important;
    bottom: -8px !important;
    right: -20px !important;
    width: 42px !important;
    height: 42px !important;
    background-color: #e8e8e8 !important;

    -webkit-mask: url("https://i.postimg.cc/Kv8fm1bg/72EF494CB999BDD63C5898A258F9FB45.png") no-repeat center / contain;
    mask: url("https://i.postimg.cc/Kv8fm1bg/72EF494CB999BDD63C5898A258F9FB45.png") no-repeat center / contain;

    pointer-events: none !important;
    z-index: 5 !important;
}

/* 中间和最后一条消息不显示尾巴 */
[data-theme-style="qq"] .msg-bubble-wrapper.is-mid .bubble-them-custom::before,
[data-theme-style="qq"] .msg-bubble-wrapper.is-last .bubble-them-custom::before,
[data-theme-style="qq"] .msg-bubble-wrapper.is-mid .bubble-me-custom::before,
[data-theme-style="qq"] .msg-bubble-wrapper.is-last .bubble-me-custom::before {
    display: none !important;
}

